import {money} from './model.mjs';
export const months=['January','February','March','April','May','June','July','August','September','October','November','December'];
export const history=months.map((name,index)=>{const budget=[40000,41000,40000,42000,42000,43000,43000,44000,44000][index];const spent=[37200,39500,38600,43100,40400,41800,42700,40900,42100][index];return {month:index+1,name,budget:budget??null,spent:spent??null};});
export function monthSelector(selected){return `<div class="month-control"><span class="eyebrow">Your timeline</span><button type="button" class="calendar-trigger" data-calendar="open" aria-haspopup="dialog"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6"><rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 2v6m10-6v6M3 11h18"/></svg><span>${months[selected-1]} 2026</span></button></div>`;}
export function calendarGrid(month,day=null){const first=new Date(Date.UTC(2026,month-1,1)).getUTCDay();const days=new Date(Date.UTC(2026,month,0)).getUTCDate();return `<div class="calendar-navigation"><button type="button" data-calendar="previous" aria-label="Previous month" ${month===1?'disabled':''}>←</button><h3>${months[month-1]} 2026</h3><button type="button" data-calendar="next" aria-label="Next month" ${month===12?'disabled':''}>→</button></div><div class="calendar-weekdays" aria-hidden="true">${['S','M','T','W','T','F','S'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-days">${'<span></span>'.repeat(first)}${Array.from({length:days},(_,i)=>`<button type="button" data-calendar="day" data-day="${i+1}" aria-label="${months[month-1]} ${i+1}, 2026" ${day===i+1?'aria-pressed="true"':''} ${month===10&&i===3?'class="calendar-today" aria-current="date"':''}>${i+1}</button>`).join('')}</div>`;}
export function monthView(selected,route){const data=history[selected-1],past=selected<10;const groups=past?[{name:'Housing & utilities',amount:24000},{name:'Food & groceries',amount:Math.round((data.spent-24000)*.55)},{name:'Transport & lifestyle',amount:data.spent-24000-Math.round((data.spent-24000)*.55)}]:[];return `<main id="main" tabindex="-1" class="ecosystem-page fade"><div class="page-heading"><div><div class="eyebrow">${past?'Historical demo snapshot':'Upcoming month'}</div><h1>${data.name} ${route==='transactions'?'spending':route==='insights'?'insights':'budget'}.</h1></div>${monthSelector(selected)}</div><p class="data-note">${past?'Illustrative monthly history, not imported bank records. These completed months are read-only and do not change your October plan.':'This month has not started. No actual spending or saved budget is available yet.'}</p>${past?`<div class="goals-grid"><section class="goal-panel"><h2>Monthly spending budget</h2><div class="detail-amount num">${money(data.budget)}</div><p>Sample budget for ${data.name}</p></section><section class="goal-panel"><h2>Actual spending · demo</h2><div class="detail-amount num">${money(data.spent)}</div><p>${data.spent<=data.budget?money(data.budget-data.spent)+' under budget':money(data.spent-data.budget)+' over budget'}</p></section></div><section class="section"><h2>Spending breakdown</h2>${groups.map(g=>`<div class="row"><span>${g.name}</span><strong class="num">${money(g.amount)}</strong></div>`).join('')}<p class="data-note">Category totals add up to ${money(data.spent)}. Individual transaction records were not supplied for this month.</p></section>`:`<section class="empty-state"><h2>Room for the next month.</h2><p>Choose a completed month to review budgets and spending, or October to explore your current plan.</p></section>`}<a class="btn secondary" href="#/history">Compare all 12 months</a></main>`;}
export function yearView(){return `<main id="main" tabindex="-1" class="ecosystem-page fade"><div class="page-heading"><div><div class="eyebrow">2026 · Demo data</div><h1>Your year, month by month.</h1><p>Completed monthly budgets and spending, alongside the current October snapshot.</p></div></div><div class="year-list">${history.map(d=>`<a class="year-row" href="#/home" data-month="${d.month}"><strong>${d.name}</strong><span>${d.month<10?'Budget '+money(d.budget):d.month===10?'Current planning snapshot':'Upcoming · no data'}</span><span>${d.month<10?'Spent '+money(d.spent):d.month===10?'Flexible ₹16,100':'—'}</span></a>`).join('')}</div><p class="data-note">January–September are illustrative completed-month totals. October uses the original live demo fixture; its partial activity is not a full-month total. November and December have no actual spending.</p></main>`;}
